import{_ as e,o,c as l,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const r="/plantuml/599d38b72caac984.svg",h=JSON.parse('{"title":"Java内存模型简介","description":"","frontmatter":{"title":"Java内存模型简介","date":"2022-06-24","categories":["编程语言","Java"],"tags":["Java","JVM"]},"headers":[],"relativePath":"编程语言/Java内存模型简介.md","filePath":"编程语言/Java内存模型简介.md"}'),i={name:"编程语言/Java内存模型简介.md"};function d(n,a,p,c,s,v){return o(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="java内存模型简介" tabindex="-1">Java内存模型简介 <a class="header-anchor" href="#java内存模型简介" aria-label="Permalink to &quot;Java内存模型简介&quot;">​</a></h1><p>Java内存模型（Java Memory Model，JMM）是Java多线程读写共享内存中的一种规范，该规范支持了<code>synchronized</code>、<code>volatile</code>、<code>final</code>、<code>Lock</code>等Java并发工具。</p><p>前面介绍了JVM内存区域，JVM内存区域和Java内存模型是不同层次对内存的划分，Java内存模型侧重描述内存数据在多线程下的读写规则，一般关注<strong>并发</strong>编程下线程如何正确读写共享数据。</p><h2 id="一定义" tabindex="-1">一、定义 <a class="header-anchor" href="#一定义" aria-label="Permalink to &quot;一、定义&quot;">​</a></h2><p>Java内存模型在JSR133规范（<a href="https://download.oracle.com/otn-pub/jcp/memory_model-1.0-pfd-spec-oth-JSpec/memory_model-1_0-pfd-spec.pdf" target="_blank" rel="noreferrer">JSR133草案</a>、<a href="https://www.cs.umd.edu/~pugh/java/memoryModel/jsr133.pdf" target="_blank" rel="noreferrer">JSR133</a>、<a href="http://ifeve.com/wp-content/uploads/2014/03/JSR133%E4%B8%AD%E6%96%87%E7%89%88.pdf" target="_blank" rel="noreferrer">JSR133-中文版</a>）中有详细的数学定义（JSR133第7小节），本文无意照本宣科引入复杂的数学概念（其实是因为看不懂囧，逃~），这里给出它的一个简单的定义（JSR133第4小节）：<strong>Java内存模型是描述Java共享变量“可见性”的一组规则，该规则阐明了一个线程对共享变量的的写操作，何时能被另一个线程观察（读）到。</strong></p><blockquote><p>JSR草案中也提到了“有序性”、“原子性”等概念，它们可以辅佐“可见性”实现正确的并发。</p></blockquote><h2 id="二内存交互" tabindex="-1">二、内存交互 <a class="header-anchor" href="#二内存交互" aria-label="Permalink to &quot;二、内存交互&quot;">​</a></h2><p>JMM有主内存和工作内存两个概念，主内存全局共享，工作内存线程独享。主内存可以类比为JVM内存区域中的“堆”，工作内存可以类比为JVM内存区域中的“栈”，但请注意，这样的类比只是便于理解，它们本身并不是相同的概念。</p><p>工作内存保存了主内存的变量副本，后续所有对变量的读写都在工作线程中进行，同时，本地内存的读写操作也将与主内存交互，由于这种交互机制的存在，不同线程对同一个变量的读写可能会发生延迟或紊乱，这也是多线程下JMM“可见性”需要解决的问题。</p><p>内存交互简单来说就是工作内存与主内存的同步读写，更宽泛来说，就涉及到8种操作，如下所示：</p><img class="diagram-image" src="'+r+'" alt="" width="291" height="423" loading="lazy" decoding="async"><h2 id="三volatile的可见性特征" tabindex="-1">三、volatile的可见性特征 <a class="header-anchor" href="#三volatile的可见性特征" aria-label="Permalink to &quot;三、volatile的可见性特征&quot;">​</a></h2><p>volatile，英文原意为“易变的”、“易失的”，这表明了工作内存中的volatile变量是不确定的，使得线程读写volatile变量时不相信当前本地内存中的值，而是立马去读写主内存中的值。结合上述内存交互的过程，volatile变量的读写有两个过程：</p><ol><li>线程往本地内存中更新一个volatile变量时，会立刻将之写到主内存中去。</li><li>线程从本地内存读取一个volatile变量时，会先将之设置为无效，并立刻从主内存中读取。</li></ol><p>上述过程保证了volatile的可见性：一个线程对volatile变量的修改对其它线程是马上可以被观察（读）到的。</p><p>同时，volatile也可以禁止重排序，当然，这个特性就和可见性没什么关系了。</p><h2 id="四总结" tabindex="-1">四、总结 <a class="header-anchor" href="#四总结" aria-label="Permalink to &quot;四、总结&quot;">​</a></h2><p>全文围绕“可见性”这个概念介绍了三点：JMM是描述Java共享变量“可见性”的一组规则，“可见性”问题普遍存在于主内存与共享内存的交互过程中，volatile是实现共享内存的“可见性”的一种方式。</p><p>JMM涉及到的概念众多，“可见性”显然只是其中一个，JMM中的“有序性”、“原子性”、“指令重排序”、“内存屏障”、“先行发生原则（Happens-Before）”等这些概念，以及Final、synchronized、Lock与JMM的关系，由于视野受限，当前暂时无法一一介绍，关于JMM的知识点个人还在持续学习中，上述内容存在理解偏差或需要补充的地方，后续将实时更新。</p><blockquote><p>参考文档</p></blockquote><ol><li>《深入理解Java虚拟机第3版 周志明 著》</li><li>《Java并发编程的艺术 方腾飞 魏鹏 程晓明 著》</li><li><a href="https://www.langnerd.com/java-memory-model/#java_memory_model" target="_blank" rel="noreferrer">Java Memory Model - LangNerd</a></li><li><a href="http://www.cs.umd.edu/~pugh/java/memoryModel/jsr-133-faq.html#whatismm" target="_blank" rel="noreferrer">JSR 133 (Java Memory Model) FAQ</a></li></ol>',21)])])}const m=e(i,[["render",d]]);export{h as __pageData,m as default};
